CREATE TABLE albums(id TEXT PRIMARY KEY,name TEXT NOT NULL,sort_name TEXT,year INTEGER,genre TEXT,cover_r2_key TEXT,song_count INTEGER,duration INTEGER,size INTEGER,compilation INTEGER,created_at INTEGER,updated_at INTEGER);
CREATE TABLE song_masters(id TEXT PRIMARY KEY,album_id TEXT NOT NULL,title TEXT NOT NULL,track INTEGER,disc INTEGER,duration INTEGER,updated_at INTEGER);
CREATE TABLE song_instances(id TEXT PRIMARY KEY,master_id TEXT NOT NULL,storage_object_id TEXT NOT NULL,suffix TEXT NOT NULL,size INTEGER,missing INTEGER NOT NULL DEFAULT 0);
CREATE TABLE storage_objects(id TEXT PRIMARY KEY,physical_key TEXT NOT NULL);
CREATE TABLE storage_entries(id TEXT PRIMARY KEY,instance_id TEXT NOT NULL,object_id TEXT NOT NULL,parent_id TEXT,path TEXT NOT NULL);
CREATE TABLE album_display_groups(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,sort_name TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE album_display_group_members(group_id TEXT NOT NULL,album_id TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(group_id,album_id));
CREATE TABLE work_queue(id TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN ('pending','processing','completed','failed')));
